sit'=>'Dağıtımda','delivered'=>'Teslim edildi','returned'=>'İade edildi','cancelled'=>'İptal'] as $k=>$v): ?><option value="<?= $k ?>"><?= $v ?></option><?php endforeach; ?></select></label><label>Açıklama<input name="note" maxlength="255"></label><button class="btn primary">Durumu kaydet</button></form><?php endif; ?><h3>Hareket geçmişi</h3><div class="timeline"><?php foreach($events as $e): ?><article class="timeline-item"><span class="timeline-dot"></span><div><strong><?= kd_e($e['to_status']) ?></strong><p><?= kd_e($e['note']) ?></p><small><?= kd_e($e['user_name']?:'Sistem') ?> · <?= kd_e(date('d.m.Y H:i',strtotime($e['created_at']))) ?></small></div></article><?php endforeach; ?></div></section></div>
